import hashlib
import subprocess


def find_user(db, name):
    cur = db.cursor()
    cur.execute(f"SELECT * FROM users WHERE name = '{name}'")  # nosec B608
    return cur.fetchone()


def backup(path):
    return subprocess.call("tar czf backup.tgz " + path, shell=True)  # nosec B602


def hash_password(password):
    return hashlib.md5(password.encode(), usedforsecurity=False).hexdigest()
